// Parse AI Agent output into structured JSON for the frontend
const output = $input.first().json.output;

let results = [];
try {
  const jsonMatch = output.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    results = JSON.parse(jsonMatch[0]);
  } else {
    results = [{ "Response": output }];
  }
} catch (e) {
  results = [{ "Response": output }];
}

return [{ json: { success: true, agent: "Product Recommendations", results: results } }];
